def reverse(text):
    result = ""
    for letter in text:
        result = letter + result
    return result

def count_vowels(text):
    vowels = "аеёиоуыэюяaeiou"
    count = 0
    for letter in text.lower():
        if letter in vowels:
            count = count + 1
    return count

def caesar(text, shift):
    result = ""
    for letter in text:
        if "a" <= letter <= "z":
            result = result + chr((ord(letter) - ord("a") + shift) % 26 + ord("a"))
        elif "A" <= letter <= "Z":
            result = result + chr((ord(letter) - ord("A") + shift) % 26 + ord("A"))
        else:
            result = result + letter
    return result
